class Solution { static class Transaction{String raw,name,city;int time,amount;Transaction(String raw){this.raw=raw;String[] parts=raw.split(",");name=parts[0];time=Integer.parseInt(parts[1]);amount=Integer.parseInt(parts[2]);city=parts[3];}}public List<String> invalidTransactions(String[] input){int n=input.length;Transaction[] transactions=new Transaction[n];boolean[] invalid=new boolean[n];for(int i=0;i<n;i++){transactions[i]=new Transaction(input[i]);invalid[i]=transactions[i].amount>1000;}for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){Transaction a=transactions[i],b=transactions[j];if(a.name.equals(b.name)&&!a.city.equals(b.city)&&Math.abs(a.time-b.time)<=60)invalid[i]=invalid[j]=true;}List<String> answer=new ArrayList<>();for(int i=0;i<n;i++)if(invalid[i])answer.add(input[i]);return answer;} }
